set lock_timeout='5s'; lock table research_evidence.evidence_records in access exclusive mode; do $migration$ declare previous_check text; begin select pg_get_expr(conbin,conrelid) into strict previous_check from pg_constraint where conrelid='research_evidence.evidence_records'::regclass and conname='evidence_records_record_id_check'; if position('EM-' in previous_check)=0 then alter table research_evidence.evidence_records drop constraint evidence_records_record_id_check; execute format('alter table research_evidence.evidence_records add constraint evidence_records_record_id_check check ((%s) OR record_id ~ %L)', previous_check, '^EM-[0-9]{3}$'); end if; end $migration$;